def report(run):
 analysis=analyze(run);cmp=json.loads((run/'comparison.json').read_text());source=json.loads((run/'data_source.json').read_text());parent=Path(source['parent']);manifest=json.loads((run/'evaluation_manifest.json').read_text());variants=list(cmp['results']);cards=[];assets={}
 def b64(a):return base64.b64encode(np.asarray(a,dtype=np.uint8).tobytes()).decode()
 for r in manifest['rows']:
  rid=r['id'];d=run/rid;t=np.load(d/'truth.npz');rgba=np.array(Image.open(d/'skin.png').convert('RGBA'));ancestor=parent
  while not (ancestor/rid/'original_views.png').exists():ancestor=Path(json.loads((ancestor/'data_source.json').read_text())['parent'])
  p=ancestor/rid/'original_views.png'
  im=Image.open(p).convert('RGB');im.thumbnail((640,340));buf=io.BytesIO();im.save(buf,format='JPEG',quality=88);data=buf.getvalue();assets[rid]=hashlib.sha256(data).hexdigest()
  cards.append(dict(id=rid,rgba=b64(rgba),valid=b64(t['valid']),truth=b64(t['labels']),predictions={v:b64(np.load(d/(v+'.npz'))['labels']) for v in variants},metrics=analysis['cases'][rid],image='data:image/jpeg;base64,'+base64.b64encode(data).decode()))
 def pct(x):return f'{x:.1%}'
 overall=''.join('<tr><td>'+NAMES[v]+'</td>'+''.join('<td>'+x+'</td>' for x in [pct(s['macro']['iou']),pct(s['macro']['precision']),pct(s['macro']['recall']),str(s['pooled']['fp']),str(s['pooled']['fn'])])+'</tr>' for v,s in cmp['results'].items())
 rare=''
 for cls in [6,9,10]:
  for v in variants:
   m=analysis['metrics'][v][str(cls)];cells=[NAMES[v],CLASSES[cls]]
   cells+= [str(m['tp']),str(m['fp']),str(m['fn']),pct(m['precision']),pct(m['recall']),pct(m['f1']),f"{m['detected_positive_skins']}/{m['positive_skins']}",str(m['binary_parent_errors_on_positive_cells'])] if m['supported'] else ['—']*8
   rare+='<tr>'+''.join('<td>'+html.escape(x)+'</td>' for x in cells)+'</tr>'
 changes=''
 for pair,values in analysis['matched_comparisons'].items():
  for cls,m in values.items():
   delta=m['precision_recall_f1_delta'];changes+='<tr>'+''.join('<td>'+str(x)+'</td>' for x in [NAMES[pair.split('__')[0]]+' → '+NAMES[pair.split('__')[1]],CLASSES[int(cls)],f"{m['delta_fp']:+d}",f"{m['delta_fn']:+d}",f'{delta[0]*100:+.1f}',f'{delta[1]*100:+.1f}',f'{delta[2]*100:+.1f}'])+'</tr>'
 payload=dict(cases=cards,names=NAMES,variants=variants,metrics=analysis['metrics']);options=''.join(f'<option value="{v}">{NAMES[v]}</option>' for v in variants)
 doc='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MC Meat · 修正版标签与有界头部细化</title><style>
:root{font-family:system-ui,-apple-system,sans-serif;color:#dce6ee;background:#111924}*{box-sizing:border-box}body{margin:0}main{max-width:1500px;margin:auto;padding:30px 22px}h1{font-size:30px}h2{font-size:20px;margin:5px 0}p{line-height:1.7;color:#afc0d1}.note{padding:14px 18px;border-left:3px solid #efbc73;background:#302a21;color:#f5dfbd}.summary{display:flex;gap:14px;flex-wrap:wrap}.summary div{flex:1;background:#1d2b3c;padding:16px;border-radius:10px;min-width:180px}.summary b{font-size:28px;color:#89dfbf;display:block}table{border-collapse:collapse;width:100%;font-size:13px;margin:15px 0;background:#1a2737}th,td{text-align:left;padding:9px;border:1px solid #35495f}th{color:#9ddfc5}.scroll{overflow:auto}details{margin:18px 0}summary{cursor:pointer;padding:8px;color:#a1cff1}.controls{position:sticky;top:0;z-index:4;background:#172433f5;padding:14px;border:1px solid #43586e;border-radius:10px;display:flex;gap:10px;flex-wrap:wrap}select,input{background:#101b28;color:#e4edf4;padding:8px;border:1px solid #5c748b;border-radius:6px;font-size:14px}article{padding:22px;background:#192738;border:1px solid #364f67;border-radius:12px;margin:24px 0}.head{display:flex;gap:24px;align-items:center;flex-wrap:wrap}.head img{max-width:360px;width:100%;border-radius:6px}.panels{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{background:#111e2c;border-radius:8px;padding:14px}.panel h3{font-size:16px;min-height:32px}.uv{width:min(100%,320px);image-rendering:pixelated}.faces{width:min(100%,480px);image-rendering:pixelated;margin-left:10px}.stats{font-size:14px;color:#b5cfe4;line-height:1.6}.legend{display:flex;gap:18px;flex-wrap:wrap;padding:14px 0}.legend span{font-size:13px}.legend i{display:inline-block;width:12px;height:12px;margin-right:6px}.count{align-self:center;color:#b1d4ec;font-size:14px}[hidden]{display:none!important}footer{font-size:13px;color:#99aec2;margin:24px 0}@media(max-width:900px){.panels{grid-template-columns:1fr}.controls{position:static}.faces{margin-left:0}main{padding:15px}}
</style><main><p>MC MEAT / CORRECTED LABELS / BOUNDED HEAD REFINEMENT / V15</p><h1>修正版标注：区分标签问题和模型问题</h1><div class="summary"><div><b>169</b>历史人工皮肤 · 两例修订</div><div><b>3 组 × 5 折</b>原标签／修正标签／有界细化</div><div><b>200 + 100</b>基础训练／头部细化，DINO 冻结</div><div><b>线上未改</b>权重仅用于实验对比</div></div><p>用户复核确认：5D74V6D8LDF3ME42 的白发 67 格、4ZVTCXVRWTB9ZW4A 的帽兜／衣领 21 格属于其他非 meat。另建修正版标注，仅将这 88 格胡子改为其他；原始标注、二分类、颜色、遮挡有效区不变。原历史胡子真值从 165 格修正为 77 格。</p><p>相同 source 五折、相同特征、相同随机种子：先重跑原标签对照，再只修标签重训；最后从每折对应的修正版权重初始化头部网络，冻结基础模型，只训练六面上下文细化。单格 logit 修正限制在 ±1，非头部输出完全不变。弱标签细类损失与人工分开，按父样本归组；保留小权重的已知难负例损失及基础分布约束。</p><p class="note">本页全部旧预测和新预测均在同一修正版真值上重新计算；不能直接和旧报告的 165 格胡子指标相减。胡子现在只有 3 张／77 格，眼影 8 张／28 格，鼻子 9 张／17 格。本页仍是反复使用的历史开发验证集，不是新盲测；弱标注与合成眼影只参与训练。</p><details open><summary>预定对照与消融</summary><p>原标签对照与只修标签组都训练 200 epoch；有界细化在同折训练数据上追加 100 epoch，基础权重冻结；没有用完整模型初始化留出折。新三组均使用固定类别阈值 0.5。变化量是右侧减左侧，负 FP/FN 表示减少。</p><div class="scroll"><table><tr><th>对照</th><th>类别</th><th>Δ误选 FP</th><th>Δ漏检 FN</th><th>Δ精确率 pp</th><th>Δ召回 pp</th><th>ΔF1 pp</th></tr>CHANGES</table></div></details><details open><summary>meat 二分类整体表现</summary><div class="scroll"><table><tr><th>版本</th><th>平均 IoU</th><th>平均精确率</th><th>平均召回</th><th>误选格</th><th>漏选格</th></tr>OVERALL</table></div></details><details><summary>稀有细类指标</summary><div class="scroll"><table><tr><th>版本</th><th>类别</th><th>TP</th><th>FP</th><th>FN</th><th>精确率</th><th>召回率</th><th>F1</th><th>命中正例皮肤</th><th>正例格二分类错误</th></tr>RARE</table></div></details>
<div class="controls"><input id="query" placeholder="图片 ID"><select id="class"><option value="6">胡子</option><option value="9">眼影</option><option value="10">鼻子</option><option value="all">所有七类</option></select><select id="scope"><option value="positive">人工标有此类</option><option value="negative">未标此类但有误选</option><option value="errors">右侧结果有错误</option><option value="all">全部案例</option></select><select id="left">OPTIONS</select><select id="right">OPTIONS</select><select id="mode"><option value="errors">逐格错误</option><option value="labels">分类覆盖</option></select><span class="count" id="count"></span></div>
<div class="legend"><span><i style="background:#3dd4a0"></i>正确命中</span><span><i style="background:#ff4761"></i>误选 FP</span><span><i style="background:#ffd15c"></i>漏检 FN</span><span>每侧：全 UV，及六面放大：每行正／右／左／下巴／后／顶；上内层、下外层</span></div><div id="cases"></div><footer>全量训练权重与留出权重分别保存。页面没有将训练样本拟合率当作泛化效果；新模型未替换线上预选。默认左右显示上一轮 v13 均衡与本轮 v15 有界细化，保留成功与退步案例。</footer></main>
<script type="application/json" id="data">PAYLOAD</script><script>
const D=JSON.parse(document.getElementById('data').textContent),E={};for(const k of ['query','class','scope','left','right','mode','count'])E[k]=document.getElementById(k);E.left.value='balanced_boundary';E.right.value='bounded_refine_v15';
function bytes(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}const colors={0:[65,70,80],1:[38,187,128],2:[0,169,232],3:[241,123,157],5:[234,154,39],6:[199,124,71],9:[183,128,237],10:[255,115,87]};
for(const c of D.cases){c.a=bytes(c.rgba);c.v=bytes(c.valid);c.t=bytes(c.truth);c.p={};for(const k of D.variants)c.p[k]=bytes(c.predictions[k]);const a=document.createElement('article');a.dataset.id=c.id;a.innerHTML='<div class="head"><img loading="lazy" src="'+c.image+'" alt="原皮肤渲染"><div><h2>'+c.id+'</h2><p>本页使用修正版人工标签。新训练各组均按 source 留出；历史参考沿用原审计口径。</p></div></div><div class="panels">'+[0,1].map(()=>'<div class="panel"><h3></h3><div class="stats"></div><canvas class="uv" width="64" height="64"></canvas><canvas class="faces" width="48" height="16"></canvas></div>').join('')+'</div>';document.getElementById('cases').appendChild(a);c.el=a;}
function known(c,model,cl){return cl==='all'||D.metrics[model][cl].supported;}
function stat(c,model,cl){if(!known(c,model,cl))return '此模型不支持该细类';if(cl==='all'){let wrong=0;for(let i=0;i<4096;i++)if(c.v[i]&&c.p[model][i]!==c.t[i])wrong++;return '七类／其他不一致 '+wrong+' 格';}const m=c.metrics[cl][model];return '正确 TP '+m.tp+' · 误选 FP '+m.fp+' · 漏检 FN '+m.fn+' · 真值 '+m.positive_cells+' 格';}
function pixels(c,model,cl,mode){const out=new Uint8ClampedArray(16384),pred=c.p[model],supported=known(c,model,cl);for(let i=0;i<4096;i++){let color=null;const x=i%64,y=Math.floor(i/64),off=i*4;if(!c.v[i]){const g=(x+y)%2?224:240;out.set([g,g,g,255],off);continue;}if(supported){if(mode==='labels'){if(cl==='all')color=colors[pred[i]];else if(pred[i]===Number(cl))color=colors[pred[i]];}else if(cl==='all'){if(pred[i]!==c.t[i])color=c.t[i]===0?[255,71,97]:[255,209,92];else if(c.t[i]>0)color=[61,212,160];}else{const truth=c.t[i]===Number(cl),selected=pred[i]===Number(cl);if(truth&&selected)color=[61,212,160];else if(selected)color=[255,71,97];else if(truth)color=[255,209,92];}}for(let j=0;j<3;j++)out[off+j]=color?Math.round(c.a[off+j]*.25+color[j]*.75):c.a[off+j];out[off+3]=255;}return out;}
function draw(c,side,model,cl,mode){const p=c.el.querySelectorAll('.panel')[side];p.querySelector('h3').textContent=D.names[model];p.querySelector('.stats').textContent=stat(c,model,cl);const uv=p.querySelector('.uv'),ctx=uv.getContext('2d');const img=ctx.createImageData(64,64);img.data.set(pixels(c,model,cl,mode));ctx.putImageData(img,0,0);const z=p.querySelector('.faces').getContext('2d');z.imageSmoothingEnabled=false;for(let layer=0;layer<2;layer++)for(const[j,xy]of[[8,8],[0,8],[16,8],[16,0],[24,8],[8,0]].entries())z.drawImage(uv,xy[0]+32*layer,xy[1],8,8,j*8,layer*8,8,8);}
function metric(c,model,cl){return c.metrics[cl][model]||{tp:0,fp:0,fn:0,positive_cells:Array.from(c.t).filter(x=>x===Number(cl)).length};}
function update(){let n=0;const cl=E.class.value;for(const c of D.cases){const m=cl==='all'?null:metric(c,E.right.value,cl);let yes=c.id.toLowerCase().includes(E.query.value.toLowerCase());if(cl!=='all'){if(E.scope.value==='positive')yes=yes&&m.positive_cells>0;if(E.scope.value==='negative')yes=yes&&m.positive_cells===0&&m.fp>0;if(E.scope.value==='errors')yes=yes&&m.fp+m.fn>0;}c.el.hidden=!yes;if(yes){n++;draw(c,0,E.left.value,cl,E.mode.value);draw(c,1,E.right.value,cl,E.mode.value);}}E.count.textContent='显示 '+n+' / '+D.cases.length+' 张';}for(const k of ['query','class','scope','left','right','mode'])E[k].addEventListener('input',update);update();
</script></html>'''
 doc=doc.replace('CHANGES',changes).replace('OVERALL',overall).replace('RARE',rare).replace('OPTIONS',options).replace('PAYLOAD',json.dumps(payload,ensure_ascii=False,separators=(',',':')))
 (run/'review_report_portable.html').write_text(doc);write(run/'report_images.json',assets);write(run/'report_provenance.json',dict(report_sha256=sha(run/'review_report_portable.html'),code_sha256=sha(Path(__file__)),comparison_sha256=sha(run/'comparison.json'),human_cases=169,embedded_renders=169))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);a=p.parse_args();report(a.run)
